#!/usr/bin/env bash
# 08.5: the held-out probes for an 08.5 run's best checkpoint (when it is not step 0) and its last adapter -- 08's set,
# generated by MLX with no PyTorch in the process (probe --generator mlx): greedy on the same 120 test questions and
# all 120 of holdout_shift, the forced probe (greedy, the 144 dev questions with a slip) and the 120 dev questions
# sampled once at T=1. Outputs go to <run>/probes-step<N>/. The seed's, 07's and 08's probes (also MLX's) are under
# 08_prover_critic_runs/ (mlx-probes/, ppo-qwen3-4b-bo4-a0.8-s0/probes-step*/): the same questions, paired.
#   ./08.5_mlx_stack_eval_heldout.sh                     waits for the run's ending.json
#   PPO_RUN=ppo-mlx-... ./08.5_mlx_stack_eval_heldout.sh
#   CKPTS="adapter-step120:120" ./08.5_mlx_stack_eval_heldout.sh   a saved checkpoint, now (07's and v1's step)
set -euo pipefail
cd "$(dirname "$0")"
export PYTHONDONTWRITEBYTECODE=1
PY=../../membrane_grpo/.venv/bin/python
R=08.5_mlx_stack_runs
PPO_RUN=${PPO_RUN:-ppo-mlx-qwen3-4b-bo4-a0.8-d37-s0}
TEST_N=${TEST_N:-120}
DEV_N=${DEV_N:-120}
probe() {  # adapter, out, split, temperature, forced, limit
    local tag="$3-T$4$([ "$6" != 0 ] && echo -n$6)-stop$([ "$5" = 1 ] && echo -forced)"
    [ -f $R/$2/$tag.json ] || $PY 08.5_mlx_stack.py probe --split $3 --stop-at-json 1 --temperature $4 --forced $5 \
        --limit $6 --generator mlx --adapter $1 --out $2
}
if [ -z "${CKPTS:-}" ]; then  # CKPTS="adapter-step120:120" probes a saved checkpoint instead (no waiting)
    while [ ! -f $R/$PPO_RUN/ending.json ]; do sleep 60; done
    while pgrep -f "08.5_mlx_stack.py ppo --out $PPO_RUN" > /dev/null; do sleep 30; done
    read BEST STOP < <(python3 -c "import json; e = json.load(open('$R/$PPO_RUN/ending.json')); print(e['best_step'], e['stopped_at'])")
    CKPTS="adapter:$STOP"
    if [ "$BEST" != 0 ] && [ "$BEST" != "$STOP" ]; then CKPTS="adapter-best:$BEST $CKPTS"; fi
fi
for pair in $CKPTS; do
    ck=${pair%%:*}
    out=$PPO_RUN/probes-step${pair##*:}
    probe $R/$PPO_RUN/$ck $out test 0 0 $TEST_N
    probe $R/$PPO_RUN/$ck $out holdout_shift 0 0 0
    probe $R/$PPO_RUN/$ck $out dev 0 1 0        # the forced probe, greedy
    probe $R/$PPO_RUN/$ck $out dev 1 0 $DEV_N   # the 120 dev questions at T=1
done
